@EnabledIfEnvironmentVariable(named="ORG_BANK_NATIVE_LEASE",matches="approved")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class BankPreparationNativeIT {
    OwnedBankPreparationFixture f;
    @BeforeAll void open()throws Exception {f=new OwnedBankPreparationFixture();}
    @AfterAll void close(){if(f!=null)f.close();}
    @BeforeEach void current()throws Exception {f.base.policyCurrent.set(true);f.base.duringObservation=()->{};f.staff(true,"actual-prepare-console");}
    long actions(UUID action)throws Exception {try(var c=f.base.admin();var s=c.prepareStatement("SELECT count(*) FROM public.org_native_action WHERE tenant_id=? AND action_id=?")){s.setObject(1,UUID.fromString(TENANT));s.setObject(2,action);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    @Test @Order(1) void actualPreparationReachesNamedNativeContextThenCreatesOnlyACompleteDraft()throws Exception {UUID bank=id(1000),action=UUID.randomUUID();byte[] body=f.desired(bank,action,300000);
        if("baseline-red".equals(System.getenv("ORG_BANK_NATIVE_STAGE"))){try{f.application.prepare(BankEnrollmentPreparationRequest.Mode.ENROLL,UUID.fromString(TENANT),bank,body).block(WAIT);}catch(RuntimeException failure){MAPPER.writeValue(f.base.run.resolve("schema-red-observation.json").toFile(),Map.of("actualMissingFunctionSqlState42883",hasSqlState(failure,"42883"),"namedFunctionObserved",hasMessage(failure,"org_native_enrollment_begin_preparation_read_context"),"scope","Actual real preparation service on originalV1-V4; no financial fixture rows"));throw failure;}}
        else {var result=f.application.prepare(BankEnrollmentPreparationRequest.Mode.ENROLL,UUID.fromString(TENANT),bank,body).block(WAIT);assertEquals("DRAFT",result.outcome().state());assertEquals(0,result.outcome().controlVersion());assertEquals("PREPARE",result.outcome().operation());assertEquals(1,actions(action));try(var c=f.base.admin();var s=c.prepareStatement("SELECT (SELECT count(*) FROM public.org_native_decision WHERE tenant_id=? AND action_id=?),(SELECT count(*) FROM public.org_native_bank_enrollment_version WHERE tenant_id=? AND proposal_id=?),(SELECT count(*) FROM public.org_native_receipt WHERE tenant_id=? AND action_id=?),(SELECT count(*) FROM public.org_native_audit WHERE tenant_id=? AND action_id=?),(SELECT count(*) FROM public.org_native_outbox WHERE tenant_id=? AND action_id=?)")){for(int i=1;i<=9;i+=2)s.setObject(i,UUID.fromString(TENANT));for(int i:List.of(2,6,8,10))s.setObject(i,action);s.setObject(4,UUID.fromString(result.outcome().proposalId()));try(var r=s.executeQuery()){r.next();assertEquals(0,r.getLong(1));assertEquals(0,r.getLong(2));for(int i=3;i<=5;i++)assertEquals(1,r.getLong(i));}}}
    }
    @Test @Order(2) void independentLiteralFullCommandHasExactPostgresCanonicalAndDigest()throws Exception {try(var input=getClass().getResourceAsStream("/authority/bank-preparation-command-v2-golden.json")){var vector=MAPPER.readTree(input);try(var c=f.base.admin();var s=c.prepareStatement("SELECT public.org_native_preparation_command(?,?,?, ?,?::json,?)")){s.setObject(1,UUID.fromString(TENANT));s.setObject(2,UUID.fromString(BANK));s.setObject(3,UUID.fromString(vector.get("actionId").textValue()));s.setString(4,vector.get("operation").textValue());s.setString(5,vector.get("original").textValue());s.setLong(6,RECEIVED);try(var r=s.executeQuery()){r.next();var result=MAPPER.readTree(r.getString(1));assertEquals(vector.get("canonical").textValue(),result.get("canonical").textValue());assertEquals(vector.get("digest").textValue(),result.get("digest").textValue());}}}}
    @Test @Order(3) void actualCreatedDraftCanBeSubmittedAndApprovedByDifferentVerifiedStaff()throws Exception {var result=f.prepare(id(1001),UUID.randomUUID(),300000);var c=new Case(99,id(1001),UUID.fromString(result.outcome().proposalId()),result.revision().originalJson(),result.outcome().recordedAtEpochMillis());assertEquals("SUBMITTED",f.base.command(c,EnrollmentProposalCommand.Operation.SUBMIT).state());f.staff(false,"actual-independent-checker");assertEquals("APPROVED",f.base.command(c,EnrollmentProposalCommand.Operation.APPROVE).state());}
    @Test @Order(4) void typedRecoveryKeepsOriginalAllocationsAfterExpiryAndRejectsChangedDesiredIntent()throws Exception {UUID bank=id(1002),action=UUID.randomUUID();byte[] desired=f.desired(bank,action,3000);var result=f.application.prepare(BankEnrollmentPreparationRequest.Mode.ENROLL,UUID.fromString(TENANT),bank,desired).block(WAIT);long until=MAPPER.readTree(desired).get("notAfterEpochMillis").longValue();long wait=until-System.currentTimeMillis()+30;if(wait>0)Thread.sleep(Math.min(wait,3100));f.staff(false,"fresh-independent-reader");int calls=f.base.sdkCalls.get();assertEquals(result,f.recovery.recover(UUID.fromString(TENANT),bank,action,desired).block(WAIT));assertEquals(calls,f.base.sdkCalls.get());var changed=(com.fasterxml.jackson.databind.node.ObjectNode)MAPPER.readTree(desired);changed.put("reason","different desired command");assertEquals(409,assertThrows(ResponseStatusException.class,()->f.recovery.recover(UUID.fromString(TENANT),bank,action,changed.toString().getBytes(StandardCharsets.UTF_8)).block(WAIT)).getStatusCode().value());assertEquals(1,actions(action));}
    @Test @Order(5) void currentPermissionWithdrawalDuringObservationPreventsAnyDraftOrAction()throws Exception {UUID action=UUID.randomUUID();f.base.duringObservation=()->f.base.policyCurrent.set(false);assertEquals(403,assertThrows(ResponseStatusException.class,()->f.prepare(id(1200),action,300000)).getStatusCode().value());assertEquals(0,actions(action));}
    @Test @Order(6) void bankSourceChangeAndRestoreCannotReviveTheCapturedPrepareTarget()throws Exception {UUID bank=id(1201),action=UUID.randomUUID();var once=new java.util.concurrent.atomic.AtomicBoolean();f.base.duringObservation=()->{if(!once.compareAndSet(false,true))return;try(var connection=f.base.admin()){OwnedBankPreparationFixture.mutateFixtureBankSource(connection,bank);}catch(Exception error){throw new AssertionError("Owned concurrent ordinary metadata mutation failed",error);}};var changed=assertThrows(RuntimeException.class,()->f.prepare(bank,action,300000));assertTrue(hasSqlState(changed,"P0001"));assertTrue(hasMessage(changed,"live preparation source changed"));assertEquals(0,actions(action));}
    @Test @Order(7) void nativeDatabaseDeadlineIsRecheckedAfterTheActualPreparationLockWait()throws Exception {UUID bank=id(1202),action=UUID.randomUUID();var held=new AtomicReference<java.sql.Connection>();f.base.duringObservation=()->{if(held.get()!=null)return;try{var c=f.base.admin();c.setAutoCommit(false);try(var s=c.prepareStatement("SELECT bank_id FROM public.org_native_bank_gate WHERE bank_id=? FOR UPDATE")){s.setObject(1,bank);s.executeQuery().close();}held.set(c);}catch(Exception e){throw new AssertionError(e);}};var executor=Executors.newSingleThreadExecutor();try{byte[] desired=f.desired(bank,action,1000);var future=executor.submit(()->f.application.prepare(BankEnrollmentPreparationRequest.Mode.ENROLL,UUID.fromString(TENANT),bank,desired).block(WAIT));long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);boolean waiting=false;while(System.nanoTime()<until){try(var c=f.base.admin();var s=c.createStatement();var r=s.executeQuery("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE usename='org_native_runtime' AND wait_event_type='Lock' AND query LIKE '%org_native_enrollment_lock_context%')")){r.next();waiting=r.getBoolean(1);}if(waiting)break;Thread.sleep(20);}assertTrue(waiting);Thread.sleep(1200);held.get().commit();held.get().close();held.set(null);var error=assertThrows(ExecutionException.class,()->future.get(10,TimeUnit.SECONDS));assertTrue(hasSqlState(error,"42501"));assertTrue(hasMessage(error,"expired after wait"));assertEquals(0,actions(action));}finally{if(held.get()!=null){held.get().rollback();held.get().close();}executor.shutdownNow();}}
    @Test @Order(8) void runtimeParentProjectionHasOnlyTheDeclaredColumnPrivileges()throws Exception {try(var c=f.base.runtime();var s=c.createStatement();var r=s.executeQuery("SELECT has_column_privilege(current_user,'public.org_native_bank_enrollment_version','bank_id','SELECT'),has_column_privilege(current_user,'public.org_native_bank_enrollment_version','ownership_generation_at_admission','SELECT'),has_column_privilege(current_user,'public.org_native_bank_enrollment_version','approved_revision_original','SELECT'),has_column_privilege(current_user,'public.org_native_bank_enrollment_version','approved_revision_canonical','SELECT'),has_table_privilege(current_user,'public.org_native_bank_enrollment_version','INSERT'),has_table_privilege(current_user,'public.org_native_bank_enrollment_control','UPDATE'),has_schema_privilege(current_user,'public','CREATE')")){r.next();assertTrue(r.getBoolean(1));assertTrue(r.getBoolean(2));for(int i=3;i<=7;i++)assertFalse(r.getBoolean(i));}}
    @Test @Order(9) void incompleteMappedPreparationGraphRollsBackWithoutAnAppliedAction()throws Exception {UUID bank=id(1003),action=UUID.randomUUID();var a=f.admitted(bank,action,6000);UUID nonce=UUID.randomUUID();var packet=PreparationWriteEvidenceCodec.context(a,nonce);var contexts=f.base.context.getBean(NativeEnrollmentContextRepository.class);var preparations=f.base.context.getBean(NativeEnrollmentPreparationContextRepository.class);
        var partial=preparations.beginPreparation(nonce,ProposalTerminationEvidenceCodec.json(packet)).flatMap(contexts::lockContext).flatMap(stamp->{var plan=a.plan();var desired=plan.desired().request();var revision=plan.revision();var actor=a.actor();UUID tenant=UUID.fromString(TENANT),proposal=UUID.fromString(revision.request().proposalId());var key=new EnrollmentProposalKey(tenant,proposal);var command=PreparationWriteEvidenceCodec.command(a);byte[] request=command.originalJson().getBytes(StandardCharsets.UTF_8);var target=BankEnrollmentRevisionCodec.enrollmentTarget(revision.request()).request();long now=stamp.dbNowMillis();
            var header=new EnrollmentProposalRow(key,bank,UUID.fromString(INSTITUTION),UUID.fromString(ISSUER),"ENROLL",UUID.fromString(plan.allocation().enrollmentId()),actor.kind(),actor.issuer(),actor.subject(),UUID.fromString(actor.tenantId()),a.staffRealm(),UUID.fromString(actor.staffActorId()),actor.clientId(),action,now);
            var row=new EnrollmentProposalRevisionRow(new EnrollmentProposalRevisionKey(tenant,proposal,1L),"ENROLL",UUID.fromString(plan.allocation().executionActionId()),plan.local().bankGeneration(),0,plan.local().sourceGeneration(),null,desired.notAfterEpochMillis(),desired.allowedUses().stream().map(Enum::name).toList(),revision.originalJson().getBytes(StandardCharsets.UTF_8),ProposalTerminationEvidenceCodec.REVISION_ENCODING,revision.canonicalIntent(),revision.intentDigest(),now);
            var control=new EnrollmentProposalControlRow(key,"DRAFT",1,0,null,null,action);var resolved=new EnrollmentActionRow(new EnrollmentActionKey(tenant,action),bank,"PREPARE",PreparationWriteEvidenceCodec.route(a),request,command.encoding(),command.canonical(),command.digest(),"COMMAND",request,command.encoding(),command.canonical(),command.digest(),actor.kind(),actor.issuer(),actor.subject(),UUID.fromString(actor.tenantId()),a.staffRealm(),UUID.fromString(actor.staffActorId()),actor.clientId(),proposal,1L,revision.intentDigest(),"APPLIED",now);
            return f.base.operations.insert(header).then(Mono.defer(()->f.base.operations.insert(row))).then(Mono.defer(()->f.base.operations.insert(control))).then(Mono.defer(()->f.base.operations.insert(resolved)));
        });var error=assertThrows(RuntimeException.class,()->partial.as(TransactionalOperator.create(f.base.manager)::transactional).block(WAIT));assertTrue(hasSqlState(error,"P0001"));assertTrue(hasMessage(error,"preparation graph witness mismatch"));assertEquals(0,actions(action));}
}
